//! Hand-authored architectural MOV CR8 controls; generated bytes only.
use super::winhttp::call;
use super::{ApiFixture, api_probe, put32, put64};
use crate::pe::Architecture;
#[derive(Clone, Copy, Debug)]
pub enum Cr8Fixture {
    Lifecycle,
    Extended,
    Invalid,
    SelfModify,
    UserMode,
}
fn expect(code: &mut Vec<u8>, value: u32) {
    code.push(0x3d);
    code.extend(value.to_le_bytes());
    code.extend([0x74, 1, 0xcc]);
}
fn pointer(code: &mut Vec<u8>, value: u64) {
    code.extend([0x48, 0xb8]);
    code.extend(value.to_le_bytes());
}
pub fn cr8_probe(architecture: Architecture, kind: Cr8Fixture) -> Vec<u8> {
    let wide = architecture == Architecture::X64;
    let base = if wide { 0x140000000u64 } else { 0x400000 };
    let source = api_probe(architecture, ApiFixture::PoolLifecycle);
    let mut data = vec![0; 0x2200];
    data[..0x200].copy_from_slice(&source[..0x200]);
    let table = 0x98 + if wide { 0xf0 } else { 0xe0 };
    let dd = 0x98 + if wide { 112 } else { 96 };
    for (at, value) in [
        (0x98 + 4, 0x1000),
        (0x98 + 8, 0x1000),
        (0x98 + 56, 0x3000),
        (table + 8, 0x1000),
        (table + 16, 0x1000),
        (table + 40 + 8, 0x1000),
        (table + 40 + 16, 0x1000),
        (table + 40 + 20, 0x1200),
        (dd + 8, 0x2000),
        (dd + 12, 40),
        (0x1200, 0x2180),
        (0x120c, 0x2040),
        (0x1210, 0x2080),
    ] {
        put32(&mut data, at, value);
    }
    data[0x1240..0x124d].copy_from_slice(b"ntoskrnl.exe\0");
    if wide {
        for at in [0x1280, 0x1380] {
            put64(&mut data, at, 0x2300);
        }
    } else {
        for at in [0x1280, 0x1380] {
            put32(&mut data, at, 0x2300);
        }
        data[0x200..0x202].copy_from_slice(&[0x0f, 0x0b]);
        return data;
    }
    data[0x1502..0x1512].copy_from_slice(b"KeGetCurrentIrql");
    if matches!(kind, Cr8Fixture::UserMode) {
        data[0x98 + 68..0x98 + 70].copy_from_slice(&3u16.to_le_bytes());
    }
    if matches!(kind, Cr8Fixture::SelfModify) {
        put32(&mut data, table + 36, 0xe0000020);
        data[0xa00..0xa05].copy_from_slice(&[0x44, 0x0f, 0x22, 0xc0, 0xc3]);
    }
    let mut code = vec![0x53, 0x48, 0x83, 0xec, 0x60];
    code.extend([0x49, 0xb9]);
    code.extend(0x1122334455667788u64.to_le_bytes());
    code.extend([0xf9]); // Carry must survive both real MOV instructions.
    if matches!(kind, Cr8Fixture::Extended) {
        code.extend([0x49, 0xbb]);
        code.extend(13u64.to_le_bytes());
        code.extend([
            0x45, 0x0f, 0x22, 0xc3, 0x45, 0x0f, 0x20, 0xc2, 0x4c, 0x89, 0xd0,
        ]);
    } else {
        pointer(
            &mut code,
            if matches!(kind, Cr8Fixture::Invalid) {
                16
            } else {
                13
            },
        );
        if matches!(kind, Cr8Fixture::SelfModify) {
            let next = 0x1000 + code.len() + 5;
            code.push(0xe8);
            code.extend((0x1800i32 - next as i32).to_le_bytes());
        } else {
            code.extend([0x44, 0x0f, 0x22, 0xc0]);
        }
        code.extend([0x44, 0x0f, 0x20, 0xc0]);
    }
    // Snapshot flags before CMP modifies them; only inspect the carry bit.
    code.extend([0x9c, 0x5a]);
    expect(&mut code, 13);
    code.extend([0x83, 0xe2, 1, 0x83, 0xfa, 1, 0x74, 1, 0xcc]);
    code.extend([0x4c, 0x89, 0xc8, 0x48, 0xba]);
    code.extend(0x1122334455667788u64.to_le_bytes());
    code.extend([0x48, 0x39, 0xd0, 0x74, 1, 0xcc]);
    if matches!(kind, Cr8Fixture::Extended) {
        code.extend([0x4c, 0x89, 0xd8]);
        expect(&mut code, 13);
    }
    code.extend([0x65, 0x0f, 0xb6, 0x04, 0x25, 0x50, 0, 0, 0]);
    expect(&mut code, 13);
    call(&mut code, true, base, 0, &[]);
    expect(&mut code, 13);
    if matches!(kind, Cr8Fixture::SelfModify) {
        pointer(&mut code, base + 0x1802);
        code.extend([0x66, 0xc7, 0, 0x20, 0xc3, 0x31, 0xc0]);
        let next = 0x1000 + code.len() + 5;
        code.push(0xe8);
        code.extend((0x1800i32 - next as i32).to_le_bytes());
        code.extend([0x48, 0x89, 0xd8]);
        expect(&mut code, 13);
    }
    code.extend([0x31, 0xc0, 0x44, 0x0f, 0x22, 0xc0, 0x44, 0x0f, 0x20, 0xc0]);
    expect(&mut code, 0);
    call(&mut code, true, base, 0, &[]);
    expect(&mut code, 0);
    code.extend([0xb8, 1, 0, 0, 0, 0x48, 0x83, 0xc4, 0x60, 0x5b, 0xc3]);
    assert!(code.len() < 0x800);
    data[0x200..0x200 + code.len()].copy_from_slice(&code);
    data
}
